-- Table: hrm_payroll_detail_component
-- Source: accounting_admin_db.sql (7. HRMIS)
--
-- One migration per table. Do not edit this file after it has been applied;
-- add a new migration for later schema changes.

CREATE TABLE IF NOT EXISTS hrm_payroll_detail_component (
    id                BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    payroll_detail_id BIGINT NOT NULL REFERENCES hrm_payroll_detail(id) ON DELETE CASCADE,
    component_id      BIGINT NOT NULL REFERENCES masterdata_payroll_component(id),
    amount            NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (amount >= 0),
    notes             TEXT,
    UNIQUE (payroll_detail_id, component_id)
);
